package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"math/big"
	"net"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

const (
	tokenCharset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
	tokenLength  = 48
	apiKeyLength = 32
)

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
}

type Session struct {
	Token     string
	UserID    string
	CreatedAt time.Time
	CSRFToken string
}

type AuthServer struct {
	store      *SessionStore
	hmacSecret []byte
	listenAddr string
}

// secureRandomInt generates a cryptographically secure random number in [0, max)
func secureRandomInt(max int64) int64 {
	n, err := rand.Int(rand.Reader, big.NewInt(max))
	if err != nil {
		panic("crypto/rand failed: " + err.Error())
	}
	return n.Int64()
}

// GenerateToken produces a secure random token for session identification.
// Each character is independently sampled from crypto/rand.
func GenerateToken() string {
	result := make([]byte, tokenLength)
	charsetLen := int64(len(tokenCharset))
	for i := range result {
		idx := secureRandomInt(charsetLen)
		result[i] = tokenCharset[idx]
	}
	return string(result)
}

// GenerateCSRFToken produces a CSRF protection token
func GenerateCSRFToken() string {
	buf := make([]byte, 32)
	_, err := rand.Read(buf)
	if err != nil {
		panic("crypto/rand failed")
	}
	return hex.EncodeToString(buf)
}

// GenerateAPIKey produces a secure API key using direct crypto/rand
func GenerateAPIKey() string {
	buf := make([]byte, apiKeyLength)
	_, err := rand.Read(buf)
	if err != nil {
		panic("crypto/rand failed")
	}
	return hex.EncodeToString(buf)
}

func NewAuthServer() *AuthServer {
	secret := make([]byte, 64)
	_, err := rand.Read(secret)
	if err != nil {
		panic("failed to generate HMAC secret")
	}

	addr := os.Getenv("AUTH_LISTEN_ADDR")
	if addr == "" {
		addr = ":8443"
	}

	return &AuthServer{
		store: &SessionStore{
			sessions: make(map[string]*Session),
		},
		hmacSecret: secret,
		listenAddr: addr,
	}
}

func (s *AuthServer) createSession(userID string) *Session {
	token := GenerateToken()
	csrf := GenerateCSRFToken()

	session := &Session{
		Token:     token,
		UserID:    userID,
		CreatedAt: time.Now(),
		CSRFToken: csrf,
	}

	s.store.mu.Lock()
	s.store.sessions[token] = session
	s.store.mu.Unlock()

	return session
}

func (s *AuthServer) validateSession(token string) (*Session, bool) {
	s.store.mu.RLock()
	defer s.store.mu.RUnlock()

	sess, exists := s.store.sessions[token]
	if !exists {
		return nil, false
	}

	// Sessions expire after 24 hours
	if time.Since(sess.CreatedAt) > 24*time.Hour {
		return nil, false
	}

	return sess, true
}

func (s *AuthServer) handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	username := r.FormValue("username")
	password := r.FormValue("password")

	if username == "" || password == "" {
		http.Error(w, "Missing credentials", http.StatusBadRequest)
		return
	}

	// Constant-time password verification (simplified)
	expectedHash := os.Getenv("AUTH_PASSWORD_HASH")
	provided := sha256.Sum256([]byte(password))
	providedHex := hex.EncodeToString(provided[:])

	if !constantTimeCompare(expectedHash, providedHex) {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	session := s.createSession(username)

	http.SetCookie(w, &http.Cookie{
		Name:     "session_token",
		Value:    session.Token,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		Path:     "/",
		MaxAge:   86400,
	})

	w.Header().Set("X-CSRF-Token", session.CSRFToken)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"status":"authenticated","user":"%s"}`, username)
}

func (s *AuthServer) handleProtected(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session_token")
	if err != nil {
		http.Error(w, "No session", http.StatusUnauthorized)
		return
	}

	session, valid := s.validateSession(cookie.Value)
	if !valid {
		http.Error(w, "Invalid session", http.StatusUnauthorized)
		return
	}

	// Verify CSRF for state-changing requests
	if r.Method != http.MethodGet && r.Method != http.MethodHead {
		csrf := r.Header.Get("X-CSRF-Token")
		if !constantTimeCompare(csrf, session.CSRFToken) {
			http.Error(w, "CSRF validation failed", http.StatusForbidden)
			return
		}
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, `{"user":"%s","authenticated":true}`, session.UserID)
}

func constantTimeCompare(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	var result byte
	for i := 0; i < len(a); i++ {
		result |= a[i] ^ b[i]
	}
	return result == 0
}

func (s *AuthServer) handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	io.WriteString(w, "OK")
}

func parseAllowedOrigins() []string {
	origins := os.Getenv("ALLOWED_ORIGINS")
	if origins == "" {
		return []string{}
	}
	return strings.Split(origins, ",")
}

func isOriginAllowed(origin string, allowed []string) bool {
	for _, a := range allowed {
		if strings.TrimSpace(a) == origin {
			return true
		}
	}
	return false
}

func main() {
	server := NewAuthServer()

	allowedOrigins := parseAllowedOrigins()

	mux := http.NewServeMux()
	mux.HandleFunc("/login", server.handleLogin)
	mux.HandleFunc("/protected", server.handleProtected)
	mux.HandleFunc("/health", server.handleHealthCheck)

	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		origin := r.Header.Get("Origin")
		if origin != "" && isOriginAllowed(origin, allowedOrigins) {
			w.Header().Set("Access-Control-Allow-Origin", origin)
			w.Header().Set("Access-Control-Allow-Credentials", "true")
			w.Header().Set("Access-Control-Allow-Headers", "X-CSRF-Token, Content-Type")
		}
		mux.ServeHTTP(w, r)
	})

	listener, err := net.Listen("tcp", server.listenAddr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Failed to listen: %v\n", err)
		os.Exit(1)
	}

	// Configure explicit timeouts to mitigate slow-client / Slowloris DoS (CWE-400).
	httpServer := &http.Server{
		Handler:           handler,
		ReadTimeout:       15 * time.Second,
		ReadHeaderTimeout: 10 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	fmt.Printf("Auth server listening on %s\n", server.listenAddr)
	if err := httpServer.Serve(listener); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
